storage.rules:
rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {
    match /schools/{userId}/{allPaths=**} {
      allow read: if true;
      allow write: if request.auth != null && request.auth.uid == userId;
    }
    match /parents/{userId}/{allPaths=**} {
      allow read: if true;
      allow write: if request.auth != null && request.auth.uid == userId;
    }
    match /announcements/{allPaths=**} {
      allow read: if true;
      allow write: if request.auth != null;
    }
  }
}
